/// Raven `Blocked_Mover`.
///
/// Source: `oracle/oracle/codemp/game/g_ICARUScb.c:635-658`
pub fn Blocked_Mover(
    ctx: GameContext<'_>,ent: *mut gentity_t, other: *mut gentity_t) {
    unsafe {
        // remove anything other than a client -- no longer the case

        // don't remove security keys or goodie keys
        if (*other).s.eType == entityType_t::ET_ITEM as c_int {
            // should we be doing anything special if a key blocks it... move it somehow..?
        } else if (*other).s.number != 0
            && ((*other).client.is_null()
                || (!(*other).client.is_null()
                    && (*other).health <= 0
                    && (*other).r.contents == CONTENTS_CORPSE
                    && (*other).message.is_null()))
        {
            // if your not a client, or your a dead client remove yourself...
            // if an item or weapon can we do a little explosion..?
            G_FreeEntity(ctx, other);
            return;
        }

        if (*ent).damage != 0 {
            // Raven passes `NULL` for `dir`/`point`; `vec3_t` is a by-value
            // array here (no null representation), so the zero vector
            // (`vec3_origin`) is the faithful stand-in.
            G_Damage(
                other,
                ent,
                ent,
                vec3_origin,
                vec3_origin,
                (*ent).damage,
                0,
                MOD_CRUSH as c_int,
            );
        }
    }
}

